    result = [row[:] for row in grid]

    # Step 1: Horizontal fill
    for r in range(rows):
        marker_cols = [c for c in range(cols) if grid[r][c] != 0]
        if len(marker_cols) < 2:
            continue
        for i in range(len(marker_cols) - 1):
            left = marker_cols[i]
            right = marker_cols[i + 1]
            for c in range(left + 1, right):
                if grid[r][c] == 0:
                    result[r][c] = 3

    # Step 2: Vertical extension from horizontal fill points
    for c in range(cols):
        # Find all 3s in this column from horizontal fills (not from vertical fills yet)
        # Find markers above and below each 3
        for r in range(rows):
            if result[r][c] == 3:
                # Look for nearest marker above
                r_up = r - 1
                while r_up >= 0 and result[r_up][c] == 0:
                    r_up -= 1
                r_down = r + 1
                while r_down < rows and result[r_down][c] == 0:
                    r_down += 1

